// === Tab: mySketch ===
let theShader;
let pal;
let arr_pal;
let col =[
        ["#a6d609","#a6d609","000000","000000","#000000"]];
let h = 1080;
let w = 1920;

function preload(){
  theShader = loadShader('https://openprocessing.org/sketch/1277995/files/shader.vert', 'shader (2).frag');
}

function pal_to_arr(pal){
  let arr = [];
	let t;
	for(let i = 0; i < 5; i++){

		t  = color(pal[i])._array
		//print(t)
		t.slice(3)
		arr.push(t)
	}
	return arr
}


function setup() {
  createCanvas(w, h, WEBGL);
	n = floor(random(col.length ))
	//print(n)
	pal = col [n]
	//print(pal)

	arr_pal = pal_to_arr(pal)
	//print(arr_pal)

}

function draw() {

  shader(theShader);

	theShader.setUniform("u_k", [((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * 0.0003 - 0.0006)%0.4, ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) * 0.0003 - 0.0006 )%0.4]);

  theShader.setUniform("u_resolution", [4000, 7000]);
  theShader.setUniform("u_time", millis() / 1000.0);

	theShader.setUniform("u_col0", arr_pal[0]);
	theShader.setUniform("u_col1", arr_pal[1]);
	theShader.setUniform("u_col2", arr_pal[2]);
	theShader.setUniform("u_col3", arr_pal[3]);
	theShader.setUniform("u_col4", arr_pal[4]);
	theShader.setUniform("u_col5", arr_pal[4]);
	theShader.setUniform("u_col6", arr_pal[4]);

  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

